<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import L from 'leaflet';
type Node={camera_id:string;camera_name?:string;building_id:string;building_name?:string;area_id?:string;longitude:number;latitude:number;timestamp:string;end_timestamp:string;local_id:string};
type Path={global_id:string;activity_type:string;start_time:string;end_time:string;score:number;confidence:number|null;nodes:Node[];segments?:{coordinates:number[][]}[];raw_pixel_tracks:unknown[];raw_match:unknown};
type Result={global_id_count?:number;source:string;data_notice:string;cameras:Node[];paths:Path[];warnings:string[];disclaimer:string};
const props=defineProps<{map:L.Map|undefined;enabled:boolean}>();
const source=ref('DEMO'),task=ref(''),videoStart=ref('2026-09-16T07:00:00+08:00'),result=ref<Result>(),error=ref(''),loading=ref(false),selected=ref<Path>(),categories=ref<string[]>([]),globalId=ref(''),camera=ref(''),building=ref(''),score=ref(0),confidence=ref(0),start=ref(''),end=ref('');
const groups=new Map<string,L.LayerGroup>();let cameraLayer:L.LayerGroup|undefined;
const liveStatus=ref('尚未检查实时服务');
async function checkLive(){try{const response=await fetch('/api/cross-camera-adapter/health');if(!response.ok)throw new Error();const state=await response.json();liveStatus.value=state.message+(state.time_notice?'；'+state.time_notice:'');if(!videoStart.value&&state.video_start_time)videoStart.value=state.video_start_time}catch{liveStatus.value='实时服务状态检查失败'}}
watch(source,()=>{selected.value=undefined;result.value=undefined;for(const group of groups.values())group.remove();groups.clear();cameraLayer?.remove();if(source.value==='LIVE'){videoStart.value='';void checkLive()}});
const types=computed(()=>[...new Set(result.value?.paths.map(x=>x.activity_type)||[])]);
const visible=computed(()=>result.value?.paths.filter(p=>categories.value.includes(p.activity_type)&&(!globalId.value||p.global_id.toLowerCase().includes(globalId.value.toLowerCase()))&&p.score>=score.value&&(confidence.value===0||(p.confidence!==null&&p.confidence>=confidence.value))&&(!camera.value||p.nodes.some(n=>n.camera_id===camera.value))&&(!building.value||p.nodes.some(n=>n.building_id===building.value))&&(!start.value||new Date(p.end_time)>=new Date(start.value))&&(!end.value||new Date(p.start_time)<new Date(end.value)))||[]);
const nodeCount=computed(()=>new Set(visible.value.flatMap(p=>p.nodes.map(n=>n.camera_id))).size);
const colors=['#ffcc49','#e87eff','#49caff','#5fe0a1','#ff866d'];
function draw(){if(!props.map)return;const active=new Set(props.enabled?visible.value.map(p=>p.global_id):[]);for(const [gid,group] of groups){if(!active.has(gid)){group.remove();groups.delete(gid)}}
 for(const p of visible.value){if(!props.enabled||groups.has(p.global_id))continue;const group=L.layerGroup(),color=colors[types.value.indexOf(p.activity_type)%colors.length];
 const coords=p.nodes.filter(n=>Number.isFinite(n.longitude)&&Number.isFinite(n.latitude)).map(n=>[n.latitude,n.longitude] as L.LatLngTuple);
 const lines=p.segments?p.segments.map(s=>s.coordinates.map(c=>[c[1],c[0]] as L.LatLngTuple)):[coords];
 for(const line of lines)if(line.length>1)L.polyline(line,{color,weight:3,opacity:.85,dashArray:'10 7',className:result.value?.source==='DEMO'?'demo-activity-flow':''}).on('click',()=>selected.value=p).addTo(group);
 coords.forEach((coord,index)=>L.circleMarker(coord,{radius:index===0||index===coords.length-1?6:4,color,fillOpacity:1}).on('click',()=>selected.value=p).bindTooltip(`${p.global_id} · ${index===0?'起点':index===coords.length-1?'终点':'中间节点'}`).addTo(group));
 group.addTo(props.map);groups.set(p.global_id,group)}
 if(props.enabled&&cameraLayer&&!props.map.hasLayer(cameraLayer))cameraLayer.addTo(props.map);if(!props.enabled)cameraLayer?.remove();}
async function load(){loading.value=true;error.value='';if(source.value==='LIVE')await checkLive();try{const response=await fetch('/api/cross-camera-adapter/paths',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:source.value,task_id:task.value||null,video_start_time:videoStart.value||null,allow_demo_fallback:false})});if(!response.ok)throw new Error((await response.json()).detail||'轨迹数据加载失败');result.value=await response.json();categories.value=types.value;for(const group of groups.values())group.remove();groups.clear();cameraLayer?.remove();cameraLayer=L.layerGroup();for(const n of result.value!.cameras){if(Number.isFinite(n.latitude)&&Number.isFinite(n.longitude))L.circleMarker([n.latitude,n.longitude],{radius:5,color:'#e8ffff',fillColor:'#058b9c',fillOpacity:1,weight:2}).bindTooltip(`${n.camera_id} · ${n.camera_name||''}`).addTo(cameraLayer)}draw()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch(()=>props.enabled,enabled=>{if(enabled&&!result.value)void load();else draw()});watch(visible,draw);watch(()=>props.map,draw);
onBeforeUnmount(()=>{for(const group of groups.values())group.remove();cameraLayer?.remove()});
</script>
<style>
.demo-activity-flow{animation:campus-activity-flow 3s linear infinite}
@keyframes campus-activity-flow{to{stroke-dashoffset:-34}}
@media(prefers-reduced-motion:reduce){.demo-activity-flow{animation:none}}
</style>
<style scoped>
.group-actions{display:flex;gap:6px;margin-bottom:8px}
.group-hint{line-height:1.6;color:#a4d3dd}
.activity-color{display:inline-block;width:9px;height:9px;border-radius:50%;flex:none}
.categories label{align-items:center;padding:5px 3px;background:#ffffff09}
</style>
<template><div v-if="enabled" class="trajectory-panel" data-testid="trajectory-panel"><b>多人跨镜活动路径</b><div class="row"><select v-model="source"><option value="DEMO">示范数据</option><option value="LIVE">实时接口</option></select><button @click="load" :disabled="loading">{{loading?'加载中…':'加载轨迹'}}</button></div><template v-if="source==='LIVE'"><p>{{liveStatus}}</p><input v-model="task" placeholder="跨镜任务编号"><input v-model="videoStart" placeholder="视频开始时间（含时区）"></template><p>{{result?.data_notice}}</p><p v-if="error" class="warning">{{error}}</p><p v-for="w in result?.warnings" :key="w" class="warning">{{w}}</p><p class="group-hint">活动分组可多选，勾选增加一组，取消仅移除该组。</p><div class="group-actions"><button @click="categories=[...types]">全部显示</button><button @click="categories=[]">全部隐藏</button></div><div class="categories"><label v-for="kind in types" :key="kind"><input type="checkbox" v-model="categories" :value="kind"><i class="activity-color" :style="{background:colors[types.indexOf(kind)%colors.length]}"></i>{{kind}} {{result?.paths.filter(p=>p.activity_type===kind).length}}</label></div><div class="filters"><input v-model="globalId" placeholder="匿名编号"><select v-model="camera"><option value="">全部摄像头</option><option v-for="n in result?.cameras" :key="n.camera_id" :value="n.camera_id">{{n.camera_id}}</option></select><select v-model="building"><option value="">全部建筑</option><option v-for="n in result?.cameras" :key="n.camera_id" :value="n.building_id">{{n.building_name||n.building_id}}</option></select><label>最低匹配分数 <input v-model.number="score" type="number" min="0" max="1" step=".05"></label><label>最低置信度 <input v-model.number="confidence" type="number" min="0" max="1" step=".05"></label><input v-model="start" type="datetime-local" aria-label="轨迹开始时间"><input v-model="end" type="datetime-local" aria-label="轨迹结束时间"></div><p v-if="result?.source==='LIVE'">上游匿名编号 {{result.global_id_count}} · 已映射路径 {{result.paths.length}}</p><p>当前匿名编号 {{visible.length}} · 轨迹 {{visible.filter(p=>p.nodes.length>1).length}} · 摄像头节点 {{nodeCount}}</p><div class="path-list"><button v-for="p in visible" :key="p.global_id" @click="selected=p">{{p.global_id}} · {{p.activity_type}} · {{(p.score*100).toFixed(1)}}%</button></div><p v-if="result?.source==='DEMO'" class="group-hint">25位匿名对象的示范活动路径。虚线流动仅表达活动顺序，不表示实时人员定位；活动分组不是身份类别。</p><small>{{result?.disclaimer}}</small><div v-if="selected" class="trajectory-detail"><button @click="selected=undefined">关闭详情</button><h3>{{selected.global_id}} · {{selected.activity_type}}</h3><p>起始：{{selected.start_time}}</p><p>结束：{{selected.end_time}}</p><p>经过：{{selected.nodes.map(n=>n.camera_id).join(' → ')}}</p><p>起点：{{selected.nodes[0]?.building_name||selected.nodes[0]?.building_id}}</p><p>终点：{{selected.nodes.at(-1)?.building_name||selected.nodes.at(-1)?.building_id}}</p><p>综合匹配分数：{{selected.score}}</p><p>置信度：{{selected.confidence??'上游未提供统一置信度'}}</p><p v-if="selected.nodes.length<2">仅一个有效摄像头节点，不生成跨区域连线</p><details><summary>视频画面像素轨迹</summary><pre>{{JSON.stringify(selected.raw_pixel_tracks,null,2)}}</pre></details></div></div></template>
<style scoped>.trajectory-panel{position:absolute;z-index:600;left:18px;top:135px;width:245px;max-height:65%;overflow:auto;padding:12px;background:#06384ef2;color:#e7ffff;border:1px solid #43d7d0;font:11px 'Microsoft YaHei'}.row,.filters{display:flex;flex-wrap:wrap;gap:5px}.trajectory-panel input,.trajectory-panel select,.trajectory-panel button{max-width:100%;box-sizing:border-box;background:#073043;color:#ddffff;border:1px solid #327a88;padding:4px;font-size:11px}.categories{display:grid;gap:4px}.categories label{display:flex;gap:4px}.path-list{display:grid;gap:3px;max-height:100px;overflow:auto}.warning{color:#ffd28e}.trajectory-detail{border-top:1px solid #42aab5;margin-top:8px}.trajectory-detail pre{overflow:auto;max-height:160px}.trajectory-panel small{color:#8dbfc8}</style>
